public void testRegisterMultipleNamespaces() throws RepositoryException {
    Workspace workspace = Mockito.mock(Workspace.class);
    NamespaceRegistry nsReg = mockNamespaceRegistry();
    Session session = mockSessionWithoutSessionMappings();
    when(session.getWorkspace()).thenReturn(workspace);
    when(workspace.getNamespaceRegistry()).thenReturn(nsReg);
    NamespaceHelper nsHelper = new NamespaceHelper(session);
    Map<String, String> input = Map.of("test1", "test1:", "test2", "test2", "", "test3:");
    nsHelper.registerNamespaces(input);
    // registered prefixes as suggested
    assertEquals("test1", nsReg.getPrefix("test1:"));
    // test2 is invalid namespace name, but reluctantly accepted
    assertEquals("test2", nsReg.getPrefix("test2"));
    // no prefix suggested, prefix derived from namespace name
    assertEquals("test3", nsReg.getPrefix("test3:"));
}

public void testInfoMap() throws ParserConfigurationException, TransformerException, SAXException, IOException, RepositoryException {
    Session s = Mockito.mock(Session.class);
    Mockito.when(s.getNamespaceURI("jcr")).thenReturn("http://www.jcp.org/jcr/1.0");
    Map<String, String> map = new HashMap<String, String>();
    // mandated by JCR 2.0
    map.put("srcChildRelPath", "/x");
    // OAK extension, see https://issues.apache.org/jira/browse/OAK-1669
    map.put("jcr:primaryType", "nt:unstructured");
    Document doc = DomUtil.createDocument();
    Element container = DomUtil.createElement(doc, "x", null);
    doc.appendChild(container);
    SubscriptionImpl.serializeInfoMap(container, s, map);
    ByteArrayOutputStream xml = new ByteArrayOutputStream();
    DomUtil.transformDocument(doc, xml);
    // reparse
    Document tripped = DomUtil.parseDocument(new ByteArrayInputStream(xml.toByteArray()));
    Element top = tripped.getDocumentElement();
    assertEquals("x", top.getLocalName());
    Element emap = DomUtil.getChildElement(top, ObservationConstants.N_EVENTINFO);
    assertNotNull(emap);
    Element path = DomUtil.getChildElement(emap, "srcChildRelPath", null);
    assertNotNull(path);
    Element type = DomUtil.getChildElement(emap, "primaryType", Namespace.getNamespace("http://www.jcp.org/jcr/1.0"));
    assertNotNull(type);
}

